smart.css:
.smc-root {
  color: var(--smc-text);
  font-family: var(--smc-font-body);
  line-height: 1.72;
}

.smc-article {
  display: grid;
  gap: 18px;
}

.smc-article > p {
  font-size: 17px;
}

.smc-article > p:first-child {
  color: var(--smc-primary);
  font-size: 21px;
  font-weight: 700;
  line-height: 1.55;
}

.smc-article h2 {
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-size: 29px;
  line-height: 1.25;
  padding-top: 24px;
}

.smc-article h3 {
  color: var(--smc-text);
  font-family: var(--smc-font-heading);
  font-size: 21px;
  line-height: 1.35;
}

.smc-article a {
  color: var(--smc-accent);
  font-weight: 700;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.smc-disclosure {
  background: color-mix(in srgb, var(--smc-primary) 8%, var(--smc-bg));
  border: 1px solid color-mix(in srgb, var(--smc-primary) 24%, var(--smc-border));
  border-left: 5px solid var(--smc-primary);
  border-radius: var(--smc-radius);
  padding: 18px 20px;
}

.smc-value-grid {
  display: grid;
  gap: 16px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.smc-value-card {
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  box-shadow: 0 10px 28px color-mix(in srgb, var(--smc-text) 8%, transparent);
  display: grid;
  gap: 10px;
  padding: 22px;
}

.smc-value-card h3 {
  color: var(--smc-primary);
}

.smc-checklist {
  background: color-mix(in srgb, var(--smc-accent) 7%, var(--smc-bg));
  border: 1px solid color-mix(in srgb, var(--smc-accent) 24%, var(--smc-border));
  border-radius: var(--smc-radius);
  display: grid;
  gap: 14px;
  padding: 22px;
}

.smc-checklist ul {
  display: grid;
  gap: 10px;
  list-style: disc;
  padding-left: 22px;
}

.smc-checklist li {
  padding-left: 4px;
}

@container smc (max-width: 620px) {
  .smc-article {
    gap: 15px;
  }

  .smc-article > p {
    font-size: 16px;
  }

  .smc-article > p:first-child {
    font-size: 18px;
  }

  .smc-article h2 {
    font-size: 24px;
    padding-top: 18px;
  }

  .smc-article h3 {
    font-size: 19px;
  }

  .smc-value-grid {
    grid-template-columns: 1fr;
  }

  .smc-disclosure,
  .smc-value-card,
  .smc-checklist {
    padding: 17px;
  }
}

versions.css:
.smc-root {
  font-family: var(--smc-font-body, sans-serif);
  color: var(--smc-text);
  line-height: 1.72;
  font-size: 16px;
}

.smc-article {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.smc-article p {
  margin: 0;
}

.smc-article > p:first-of-type,
.smc-article > p:nth-of-type(2) {
  padding: 18px 20px;
  background: color-mix(in srgb, var(--smc-primary) 7%, var(--smc-bg));
  border-left: 4px solid var(--smc-primary);
  border-radius: 0 var(--smc-radius) var(--smc-radius) 0;
}

.smc-article h2 {
  margin: 24px 0 0;
  padding: 0 0 9px;
  color: var(--smc-primary);
  font-family: var(--smc-font-heading, sans-serif);
  font-size: 1.45rem;
  line-height: 1.35;
  border-bottom: 2px solid color-mix(in srgb, var(--smc-primary) 22%, var(--smc-border));
}

.smc-article h3 {
  margin: 12px 0 0;
  color: var(--smc-accent);
  font-family: var(--smc-font-heading, sans-serif);
  font-size: 1.08rem;
  line-height: 1.4;
}

.smc-article a {
  color: var(--smc-primary);
  font-weight: 600;
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--smc-primary) 35%, transparent);
  text-underline-offset: 3px;
}

.smc-article a:hover {
  text-decoration-color: var(--smc-primary);
}

.smc-article strong {
  font-weight: 650;
  color: var(--smc-text);
}

@container smc (max-width: 600px) {
  .smc-root {
    font-size: 15px;
    line-height: 1.65;
  }

  .smc-article {
    gap: 14px;
  }

  .smc-article > p:first-of-type,
  .smc-article > p:nth-of-type(2) {
    padding: 14px 15px;
  }

  .smc-article h2 {
    margin-top: 18px;
    font-size: 1.22rem;
  }

  .smc-article h3 {
    font-size: 1rem;
  }
}

